#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD = 1000000007;

int add(int a, int b) {
    a += b;
    return a >= MOD ? a - MOD : a;
}

int sub(int a, int b) {
    return a >= b ? a - b : a + MOD - b;
}

long long mul(long long a, long long b) {
    return (a * b) % MOD;
}

int modPow(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = mul(res, base);
        base = mul(base, base);
        exp >>= 1;
    }
    return res;
}

int n;
int prob[8][8];
int match[8][8];
int tripleMask[7][7][7];
int fullMask;
int dp[1048576];
int finalAnswer;

bool isValid(int x, int y, int z) {
    int values[4] = {0, x, y, z};
    int indices[4] = {0, 1, 2, 3};
    do {
        bool ok = true;
        for (int i = 1; i <= 3; ++i) {
            if (!match[indices[i]][values[i]]) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    } while (next_permutation(indices + 1, indices + 4));
    return false;
}

void forwardSearch(int current, int row, int col) {
    if (!current) return;
    if (row == 4) {
        bool used[7] = {false, true, true, true, true, true, true};
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (isValid(i, j, k)) {
                        used[i] = used[j] = used[k] = false;
                        int a = -1, b = -1, c = -1;
                        for (int l = 1; l <= 6; ++l) {
                            if (!used[l]) {
                                if (a == -1) a = l;
                                else if (b == -1) b = l;
                                else c = l;
                            }
                        }
                        used[i] = used[j] = used[k] = true;
                        if (c != -1) state |= tripleMask[a][b][c];
                    }
                }
            }
        }
        dp[state] = add(dp[state], current);
        return;
    }
    match[row][col] = 1;
    int nextVal = mul(current, prob[row][col]);
    if (col == 6) forwardSearch(nextVal, row + 1, 1);
    else forwardSearch(nextVal, row, col + 1);
    match[row][col] = 0;
    nextVal = mul(current, sub(1, prob[row][col]));
    if (col == 6) forwardSearch(nextVal, row + 1, 1);
    else forwardSearch(nextVal, row, col + 1);
}

void backwardSearch(int current, int row, int col) {
    if (!current) return;
    if (row == 7) {
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (isValid(i, j, k)) state |= tripleMask[i][j][k];
                }
            }
        }
        finalAnswer = add(finalAnswer, mul(current, dp[fullMask ^ state]));
        return;
    }
    match[row - 3][col] = 1;
    int nextVal = mul(current, prob[row][col]);
    if (col == 6) backwardSearch(nextVal, row + 1, 1);
    else backwardSearch(nextVal, row, col + 1);
    match[row - 3][col] = 0;
    nextVal = mul(current, sub(1, prob[row][col]));
    if (col == 6) backwardSearch(nextVal, row + 1, 1);
    else backwardSearch(nextVal, row, col + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    int inv100 = modPow(100, MOD - 2);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            int x; cin >> x;
            prob[i][j] = mul(x, inv100);
        }
    }
    for (int i = n + 1; i <= 6; ++i) prob[i][i] = 1;
    int count = 0;
    for (int i = 1; i <= 6; ++i) {
        for (int j = i + 1; j <= 6; ++j) {
            for (int k = j + 1; k <= 6; ++k) {
                tripleMask[i][j][k] = 1 << count;
                ++count;
            }
        }
    }
    fullMask = (1 << count) - 1;
    forwardSearch(1, 1, 1);
    int totalMasks = 1 << count;
    for (int bit = 0; bit < count; ++bit) {
        for (int mask = 0; mask < totalMasks; ++mask) {
            if (mask & (1 << bit)) {
                dp[mask] = add(dp[mask], dp[mask ^ (1 << bit)]);
            }
        }
    }
    finalAnswer = 0;
    backwardSearch(1, 4, 1);
    finalAnswer = sub(1, finalAnswer);
    cout << finalAnswer << '\n';
    return 0;
}
